func spxPaper(b *port.Bitmap) int32 {
	var x int32 = 0
	var y int32 = 0
	for y < port.BitmapH(b) {
		x = 0
		for x < port.BitmapW(b) {
			port.BitmapSetU8(b, x, y, 0, 255)
			port.BitmapSetU8(b, x, y, 1, 255)
			port.BitmapSetU8(b, x, y, 2, 255)
			x += 1
		}
		y += 1
	}
	return 0
}

func spxDot(b *port.Bitmap, x int32, y int32, thick int32, r int32, g int32, bl int32) int32 {
	var i int32 = 0
	var j int32 = 0
	for j < thick {
		i = 0
		for i < thick {
			port.BitmapSetU8(b, x+i, y+j, 0, r)
			port.BitmapSetU8(b, x+i, y+j, 1, g)
			port.BitmapSetU8(b, x+i, y+j, 2, bl)
			i += 1
		}
		j += 1
	}
	return 0
}

func spxZig(b *port.Bitmap, x0 int32, y0 int32, n int32, period int32, amp int32, r int32, g int32, bl int32) int32 {
	// A pen: a zig-zag from (x0, y0) of n columns, each period `period` wide and `amp` high, two pixels thick. Draws every column and the pixels between rows so that it is connected.
	var x int32 = 0
	var ph int32 = 0
	var h int32 = 0
	var prev int32 = 0
	var y int32 = 0
	var lo int32 = 0
	var hi int32 = 0
	for x < n {
		ph = x % period
		if ph < (period / 2) {
			h = ph
		} else {
			h = period - ph
		}
		y = y0 - ((h * amp * 2) / period)
		lo = y
		hi = y
		if x > 0 {
			if prev < lo {
				lo = prev
			}
			if prev > hi {
				hi = prev
			}
		}
		y = y0 - ((h * amp * 2) / period)
		for lo <= hi {
			spxDot(b, x0+x, lo, 2, r, g, bl)
			lo += 1
		}
		prev = y
		x += 1
	}
	return 0
}

func spxLine(b *port.Bitmap, x0 int32, x1 int32, y int32) int32 {
	var x int32 = x0
	for x < x1 {
		spxDot(b, x, y, 2, 120, 120, 120)
		x += 1
	}
	return 0
}

func spxRule(rules *port.Cells, x0 int32, x1 int32, y int32) int32 {
	// A tracer rule row of page 1 from pixel (x0, y) to (x1, y) on the 72 dpi view 0: centipoints are pixels times a hundred.
	return evidence.RlNew(rules, 1, x0*100, y*100, x1*100, y*100, 0)
}

func spxFind(rules *port.Cells, ow *port.Cells, et *port.Cells, b *port.Bitmap, cand *port.Cells) int32 {
	var views *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	evidence.VwNew(views, 1, evidence.VkRender(), -1, -1, port.BitmapW(b), port.BitmapH(b), 7200, 0, -1, 0, 0, 0, 0, 0)
	return sigpx.SpFind(1, views, 0, rules, ow, et, b, 61200, cand, mask)
}

func TestAPenOverALineIsASignature(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(300, 120, 3)
	var rules *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	spxPaper(b)
	spxLine(b, 20, 280, 100)
	spxZig(b, 40, 98, 150, 24, 36, 20, 40, 120)
	spxRule(rules, 20, 280, 100)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 1, "a zig-zag pen standing on a line: one candidate")
	port.AssertEq(emonT, port.CellsAt(cand, 0), 3, "a signature")
	port.AssertThat(emonT, (port.CellsAt(cand, 2) >= 4000) && (port.CellsAt(cand, 2) <= 4500), "its box begins at the pen's first column (the first is on the rule's band, which is no ink)")
	port.AssertThat(emonT, (port.CellsAt(cand, 4) > 18000) && (port.CellsAt(cand, 4) < 19500), "and ends at its last")
	port.AssertThat(emonT, (port.CellsAt(cand, 3) > 6000) && (port.CellsAt(cand, 3) < 6800), "its top is the pen's highest point")
	port.AssertEq(emonT, port.CellsAt(cand, 7), 1321080, "its colour is the mean of its ink: (20, 40, 120)")
	port.AssertEq(emonT, port.CellsAt(cand, 9), 600, "and its confidence")
}

func TestNoRuleAShortRuleAndTheWrongInkAreNoSignature(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(300, 120, 3)
	var rules *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	spxPaper(b)
	spxZig(b, 40, 98, 150, 24, 36, 20, 40, 120)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 0, "no rule row: no zone, no candidate")
	spxRule(rules, 20, 60, 100)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 0, "a rule of 40 pt is no signature line")
	port.CellsDrop(rules, 0)
	spxRule(rules, 20, 280, 100)
	spxPaper(b)
	spxLine(b, 20, 280, 100)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 0, "a line and nothing on it")
	// a straight stroke is no pen: its path is as long as its box
	spxDot(b, 40, 80, 2, 20, 40, 120)
	var x int32 = 0
	for x < 150 {
		spxDot(b, 40+x, 80, 2, 20, 40, 120)
		x += 1
	}
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 0, "a straight line has no loops")
	// a solid block covers its box
	spxPaper(b)
	spxLine(b, 20, 280, 100)
	var y int32 = 0
	for y < 20 {
		var bx int32 = 0
		for bx < 100 {
			spxDot(b, 40+bx, 70+y, 1, 20, 40, 120)
			bx += 1
		}
		y += 1
	}
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 0, "a block of ink is a picture, not a pen")
}

func spxDashes(b *port.Bitmap, x0 int32, x1 int32, y int32) int32 {
	// A dashed straight line: dashes of 6 pixels, 3 apart, two thick.
	var x int32 = x0
	for x < x1 {
		if ((x - x0) % 9) < 6 {
			spxDot(b, x, y, 2, 120, 120, 120)
		}
		x += 1
	}
	return 0
}

func TestStackedDashedWriteInLinesAreNoSignature(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(300, 120, 3)
	var rules *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	// D1630 (smoke review A issue 16): three dashed lines over a rule (a form's write-in lines) make as long a path as a pen's loops do, in a box a pen's size; no pen draws a straight line
	spxPaper(b)
	spxLine(b, 20, 280, 100)
	spxDashes(b, 40, 250, 60)
	spxDashes(b, 40, 250, 74)
	spxDashes(b, 40, 250, 88)
	spxRule(rules, 20, 280, 100)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 0, "dashed lines are no signature")
	// the pen over the same rule still is one
	spxPaper(b)
	spxLine(b, 20, 280, 100)
	spxZig(b, 40, 98, 150, 24, 36, 20, 40, 120)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 1, "a pen is")
}

func TestAWordOcrWasSureOfIsPaper(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(300, 120, 3)
	var rules *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	spxPaper(b)
	spxLine(b, 20, 280, 100)
	spxZig(b, 40, 98, 150, 24, 36, 20, 40, 120)
	spxRule(rules, 20, 280, 100)
	port.CellsPush(et, 83)
	port.CellsPush(et, 105)
	port.CellsPush(et, 103)
	// an OCR word over the whole pen that the engine was 900 per mille sure of: the pen is text
	evidence.OwNew(ow, 1, 3000, 5500, 21000, 10500, 3000, 10500, 21000, 10500, 0, 0, 0, 3, 0, 900, -1)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 0, "the pen under a word the engine is sure of is paper: nothing is left")
	port.CellsDrop(ow, 0)
	evidence.OwNew(ow, 1, 3000, 5500, 21000, 10500, 3000, 10500, 21000, 10500, 0, 0, 0, 3, 0, 300, -1)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 1, "the same word at 300: it is the pen read as letters, and the pen is a signature")
}

