func TestACandidateIsAGroupWithNoWord(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(300, 120, 3)
	var rules *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	spxPaper(b)
	spxLine(b, 20, 280, 100)
	spxZig(b, 40, 98, 150, 24, 36, 20, 40, 120)
	spxRule(rules, 20, 280, 100)
	port.AssertEq(emonT, spxFind(rules, ow, et, b, cand), 1, "a signature")
	port.AssertEq(emonT, sigpx.SpRecord(3, cand, cg), 1, "one group")
	port.AssertEq(emonT, player.CgGet(cg, 0, player.CgfPage()), 4, "of page 4 (the argument is 0-based)")
	port.AssertEq(emonT, player.CgGet(cg, 0, player.CgfOcount()), 0, "no word")
	port.AssertEq(emonT, player.CgGet(cg, 0, player.CgfFlags()), (player.PlgInSeal()+player.PlgSealPx())+player.PlgSealSig(), "flagged in-seal, seal-px and seal-sig")
	port.AssertEq(emonT, player.CgGet(cg, 0, player.CgfRot()), 10, "its colour code: blue")
	port.AssertEq(emonT, player.CgGet(cg, 0, player.CgfX0()), port.CellsAt(cand, 2), "its box is the candidate's")
}

func TestTheLinesTheStrokesMadeAreNotThePagesText(emonT *testing.T) {
	var cand *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var ol *port.Cells = port.NewCells()
	var scr *port.Cells = port.NewCells()
	for port.CellsLen(cand) < sigpx.SpW() {
		port.CellsPush(cand, 0)
	}
	port.CellsSet(cand, 0, 3)
	port.CellsSet(cand, 2, 1000)
	port.CellsSet(cand, 3, 1000)
	port.CellsSet(cand, 4, 7000)
	port.CellsSet(cand, 5, 4000)
	// line 1: two words inside, the engine 300 sure (the strokes read as letters); line 2: one word inside at 900 (a typed name under the strokes); line 3: elsewhere
	evidence.OwNew(ow, 1, 1500, 1500, 3000, 2500, 1500, 2500, 3000, 2500, 0, 0, 0, 1, 0, 300, -1)
	evidence.OwNew(ow, 1, 3500, 1500, 5000, 2500, 3500, 2500, 5000, 2500, 0, 0, 0, 1, 0, 300, -1)
	evidence.OwNew(ow, 1, 2000, 3000, 4000, 3800, 2000, 3800, 4000, 3800, 0, 0, 0, 1, 0, 900, -1)
	evidence.OwNew(ow, 1, 30000, 30000, 32000, 31000, 30000, 31000, 32000, 31000, 0, 0, 0, 1, 0, 900, -1)
	evidence.OlNew(ol, 1, 1500, 1500, 5000, 2500, 1500, 2500, 5000, 2500, 0, 0, 0, 2)
	evidence.OlNew(ol, 1, 2000, 3000, 4000, 3800, 2000, 3800, 4000, 3800, 0, 0, 2, 1)
	evidence.OlNew(ol, 1, 30000, 30000, 32000, 31000, 30000, 31000, 32000, 31000, 0, 0, 3, 1)
	for port.CellsLen(scr) < (scan.ScSelBase() + 8) {
		port.CellsPush(scr, 0)
	}
	port.CellsSet(scr, scan.ScSelBase(), 0)
	port.CellsSet(scr, scan.ScSelBase()+1, 1)
	port.CellsSet(scr, scan.ScSelBase()+2, 2)
	port.AssertEq(emonT, sigpx.SpDropLines(scr, 3, ol, ow, cand), 2, "the strokes' line is out; the typed name the engine is sure of and the line elsewhere stay")
	port.AssertEq(emonT, port.CellsAt(scr, scan.ScSelBase()), 1, "the typed name first")
	port.AssertEq(emonT, port.CellsAt(scr, scan.ScSelBase()+1), 2, "then the other")
}
